/* Site search: in-browser full-text search over a pre-computed index.
 *
 * The index (search.json) is generated by Jekyll at build time — one record
 * per <h2> section of each listed guide. It is fetched lazily on first focus
 * of the header search box and searched with the vendored MiniSearch library
 * (assets/vendor/minisearch.min.js). No external services.
 */
(function () {
  var input = document.getElementById('search');
  var box = input && input.closest('.searchbox');
  if (!input || !box || typeof MiniSearch === 'undefined') return;

  var MAX_HITS = 8;
  var SNIPPET = 160;
  var indexUrl = input.getAttribute('data-index');

  var list = document.createElement('ul');
  list.id = 'search-results';
  list.className = 'search-results';
  list.setAttribute('role', 'listbox');
  list.setAttribute('aria-label', 'Search results');
  list.hidden = true;
  box.appendChild(list);

  input.setAttribute('role', 'combobox');
  input.setAttribute('aria-autocomplete', 'list');
  input.setAttribute('aria-controls', list.id);
  input.setAttribute('aria-expanded', 'false');

  var mini = null;
  var loading = null;
  var active = -1;

  function load() {
    if (loading) return loading;
    loading = fetch(indexUrl)
      .then(function (r) {
        if (!r.ok) throw new Error('search index ' + r.status);
        return r.json();
      })
      .then(function (docs) {
        mini = new MiniSearch({
          fields: ['heading', 'guide', 'summary', 'body'],
          storeFields: ['url', 'guide', 'heading', 'body'],
          searchOptions: {
            boost: { heading: 3, guide: 2, summary: 1.5 },
            prefix: true,
            fuzzy: 0.2
          }
        });
        mini.addAll(docs);
      })
      .catch(function (err) {
        loading = null; // allow a retry on next keystroke
        throw err;
      });
    return loading;
  }

  function search(q) {
    var hits = mini.search(q, { combineWith: 'AND' });
    if (!hits.length) hits = mini.search(q, { combineWith: 'OR' });
    return hits.slice(0, MAX_HITS);
  }

  function escapeRe(s) { return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }

  // Matched index terms (incl. fuzzy/prefix expansions) plus the raw query
  // words, longest first so the regex prefers the longest match.
  function termsFor(hit, q) {
    var words = q.toLowerCase().split(/\s+/).filter(function (w) { return w.length > 1; });
    var all = (hit.terms || []).concat(words);
    return all
      .filter(function (t, i) { return t && all.indexOf(t) === i; })
      .sort(function (a, b) { return b.length - a.length; });
  }

  // Append `text` to `el`, wrapping matches of `terms` in <mark>. Uses text
  // nodes only, so index content is never interpreted as HTML.
  function appendMarked(el, text, terms) {
    if (!terms.length) { el.appendChild(document.createTextNode(text)); return; }
    var re = new RegExp('(' + terms.map(escapeRe).join('|') + ')', 'gi');
    var last = 0, m;
    while ((m = re.exec(text)) !== null) {
      if (m.index > last) el.appendChild(document.createTextNode(text.slice(last, m.index)));
      var mark = document.createElement('mark');
      mark.textContent = m[0];
      el.appendChild(mark);
      last = m.index + m[0].length;
      if (m[0].length === 0) re.lastIndex++;
    }
    if (last < text.length) el.appendChild(document.createTextNode(text.slice(last)));
  }

  // A window of the body text around the first matched term.
  function snippet(body, terms) {
    if (!body) return '';
    var lower = body.toLowerCase();
    var at = -1;
    for (var i = 0; i < terms.length; i++) {
      var p = lower.indexOf(terms[i]);
      if (p !== -1 && (at === -1 || p < at)) at = p;
    }
    if (at === -1 || body.length <= SNIPPET) {
      return body.length > SNIPPET ? body.slice(0, SNIPPET).replace(/\s+\S*$/, '') + '…' : body;
    }
    var start = Math.max(0, at - 40);
    if (start > 0) start = body.indexOf(' ', start) + 1 || start;
    var end = Math.min(body.length, start + SNIPPET);
    var s = body.slice(start, end);
    if (end < body.length) s = s.replace(/\s+\S*$/, '') + '…';
    return (start > 0 ? '…' : '') + s;
  }

  function setActive(i) {
    var items = list.children;
    if (!items.length) { active = -1; input.removeAttribute('aria-activedescendant'); return; }
    active = (i + items.length) % items.length;
    for (var k = 0; k < items.length; k++) {
      items[k].setAttribute('aria-selected', k === active ? 'true' : 'false');
    }
    var el = items[active];
    if (el.id) input.setAttribute('aria-activedescendant', el.id);
    el.scrollIntoView({ block: 'nearest' });
  }

  function open() {
    list.hidden = false;
    input.setAttribute('aria-expanded', 'true');
  }

  function close() {
    list.hidden = true;
    input.setAttribute('aria-expanded', 'false');
    input.removeAttribute('aria-activedescendant');
    active = -1;
  }

  function render(q, hits) {
    list.textContent = '';
    active = -1;
    if (!hits.length) {
      var none = document.createElement('li');
      none.className = 'search-empty';
      none.textContent = 'No results for “' + q + '”';
      list.appendChild(none);
      open();
      return;
    }
    hits.forEach(function (hit, i) {
      var terms = termsFor(hit, q);
      var li = document.createElement('li');
      li.id = 'search-hit-' + i;
      li.setAttribute('role', 'option');
      li.setAttribute('aria-selected', 'false');

      var a = document.createElement('a');
      a.className = 'search-hit';
      a.href = hit.url;
      a.tabIndex = -1;

      var title = document.createElement('span');
      title.className = 'search-hit-title';
      appendMarked(title, hit.guide, terms);
      if (hit.heading) {
        var sep = document.createElement('span');
        sep.className = 'search-hit-sep';
        sep.textContent = ' › ';
        title.appendChild(sep);
        appendMarked(title, hit.heading, terms);
      }
      a.appendChild(title);

      var text = snippet(hit.body, terms);
      if (text) {
        var p = document.createElement('span');
        p.className = 'search-hit-snippet';
        appendMarked(p, text, terms);
        a.appendChild(p);
      }

      a.addEventListener('click', close);
      li.appendChild(a);
      li.addEventListener('mousemove', function () { if (active !== i) setActive(i); });
      list.appendChild(li);
    });
    open();
  }

  function update() {
    var q = input.value.trim();
    if (q.length < 2) { close(); list.textContent = ''; return; }
    load().then(function () {
      if (input.value.trim() !== q) return; // stale
      render(q, search(q));
    }, function () {
      list.textContent = '';
      var err = document.createElement('li');
      err.className = 'search-empty';
      err.textContent = 'Search is unavailable right now.';
      list.appendChild(err);
      open();
    });
  }

  input.addEventListener('focus', function () {
    load().catch(function () {});
    if (input.value.trim().length >= 2 && list.children.length) open();
  });
  input.addEventListener('input', update);

  input.addEventListener('keydown', function (e) {
    var hits = list.querySelectorAll('.search-hit');
    if (e.key === 'ArrowDown') {
      if (!hits.length) return;
      e.preventDefault(); open(); setActive(active + 1);
    } else if (e.key === 'ArrowUp') {
      if (!hits.length) return;
      e.preventDefault(); open(); setActive(active - 1);
    } else if (e.key === 'Enter') {
      if (!hits.length || list.hidden) return;
      e.preventDefault();
      var target = hits[active >= 0 ? active : 0];
      close();
      window.location.href = target.href;
    } else if (e.key === 'Escape') {
      if (!list.hidden) { e.preventDefault(); close(); }
      else if (input.value) { input.value = ''; }
    }
  });

  document.addEventListener('click', function (e) {
    if (!box.contains(e.target)) close();
  });

  // "/" focuses search from anywhere on the page (unless already typing).
  document.addEventListener('keydown', function (e) {
    if (e.key !== '/' || e.ctrlKey || e.metaKey || e.altKey) return;
    var t = e.target;
    if (t && (t.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName))) return;
    e.preventDefault();
    input.focus();
  });
})();
